from pedantic import validate

@validate
def int_to_roman(num: int) -> str:
    try:
        val = [
            (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
            (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
            (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'),
            (1, 'I')
        ]
        res = ''
        for (value, symbol) in val:
            while num >= value:
                res += symbol
                num -= value
        return res
    except ValueError as e:
        raise ValueError("Input must be an integer between 1 and 3999.") from e
